import { test } from "node:test";
import assert from "node:assert/strict";
import { backoffDelays } from "../src/backoff.ts";
import { callWithRetry, usedDelays } from "../src/client.ts";

test("the schedule doubles", () => {
  assert.deepEqual(backoffDelays(4, 100), [100, 200, 400]);
  assert.deepEqual(backoffDelays(1, 100), []);
});
test("a transient failure is retried", async () => {
  usedDelays.length = 0;
  let calls = 0;
  const value = await callWithRetry(async () => {
    calls += 1;
    if (calls < 3) throw new Error("transient");
    return "ok";
  }, 4, 1);
  assert.equal(value, "ok");
  assert.equal(calls, 3);
  assert.deepEqual(usedDelays, [1, 2]);
});
test("the last error survives", async () => {
  usedDelays.length = 0;
  await assert.rejects(
    callWithRetry(async () => { throw new Error("always"); }, 3, 1),
    /always/,
  );
  assert.equal(usedDelays.length, 2);
});

