UNITS = {"s": 1, "m": 60, "h": 3600, "d": 86400, "w": 604800}


def parse_duration(text):
    body = text.strip()
    if len(body) > 1 and body[-1] in UNITS and body[:-1].isdigit():
        return int(body[:-1]) * UNITS[body[-1]]
    raise ValueError("cannot parse duration %r" % text)

