    check(ring_mean(ring) == 0.0, "empty mean");
    ring.push(1);
    ring.push(2);
    ring.push(3);
    check(ring.size() == 3, "full size");
    check(std::fabs(ring_mean(ring) - 2.0) < 1e-9, "full mean");
    ring.push(4);
    check(ring.size() == 3, "size after wrap");
    check(ring.at(0) == 2, "oldest after wrap");
    check(ring.at(2) == 4, "newest after wrap");
    check(std::fabs(ring_mean(ring) - 3.0) < 1e-9, "mean after wrap");
