def rolling_max(values, width):
    if width < 1:
        raise ValueError("width must be positive")
    out = []
    for index in range(len(values)):
        start = max(0, index - width + 1)
        out.append(max(values[start : index + 1]))
    return out


def clamp_index(index, length):
    if length == 0:
        return 0
    return min(max(index, 0), length - 1)

