from src.paths import normalize


class SpecTests(unittest.TestCase):
    def test_normalize_cleans(self):
        self.assertEqual(normalize("./src/a.py"), "src/a.py")
        self.assertEqual(normalize("src//b.py"), "src/b.py")
        self.assertEqual(normalize("src/./c.py"), "src/c.py")
        self.assertEqual(normalize("src/sub/../d.py"), "src/d.py")

    def test_normalize_rejects(self):
        for bad in ("/etc/passwd", "../outside.py", "src/../../up.py"):
            with self.assertRaises(ValueError, msg=bad):
                normalize(bad)

    def test_loader_dedupes_in_order(self):
        loaded = load_paths({"paths": ["./src/a.py", "src/b.py", "src//a.py"]})
        self.assertEqual(loaded, ["src/a.py", "src/b.py"])

    def test_loader_names_the_offender(self):
        with self.assertRaises(ValueError) as ctx:
            load_paths({"paths": ["src/a.py", "../escape.py"]})
        self.assertIn("../escape.py", str(ctx.exception))


if __name__ == "__main__":
    unittest.main()

